"use client";

import { forwardRef } from "react";
import {
  Button,
  FieldError,
  Group,
  Input,
  Label,
  NumberField as AriaNumberField,
  Text,
  type NumberFieldProps as AriaNumberFieldProps,
} from "react-aria-components";
import { numberFieldDefaults, type NumberFieldSpecProps } from "../generated/number-field.types";
import { cx } from "../utils/cx";
import { fieldGroup, fieldGroupSizes } from "../utils/field";
import { MinusIcon, PlusIcon } from "../utils/icons";

export interface NumberFieldProps
  extends NumberFieldSpecProps,
    Omit<AriaNumberFieldProps, keyof NumberFieldSpecProps | "className" | "children"> {
  className?: string;
}

const stepper =
  "flex size-7 shrink-0 items-center justify-center rounded-[var(--rd-radius-control)] text-[var(--rd-color-text-muted)] outline-none " +
  "data-[hovered]:bg-[var(--rd-color-surface-subtle)] data-[hovered]:text-[var(--rd-color-text-default)] data-[pressed]:bg-[var(--rd-color-surface-subtle)] " +
  "data-[disabled]:opacity-40 data-[disabled]:cursor-not-allowed " +
  "data-[focus-visible]:ring-2 data-[focus-visible]:ring-[var(--rd-color-focus-ring)]";

const heights = {
  sm: "h-[var(--rd-size-control-sm)]",
  md: "h-[var(--rd-size-control-md)]",
  lg: "h-[var(--rd-size-control-lg)]",
} as const;

export const NumberField = forwardRef<HTMLDivElement, NumberFieldProps>(function NumberField(
  {
    label,
    description,
    errorMessage,
    showStepper = numberFieldDefaults.showStepper,
    size = numberFieldDefaults.size,
    isDisabled = numberFieldDefaults.isDisabled,
    // Left undefined unless passed: React Aria treats any defined isInvalid as
    // controlled and would hide its own validation (min, max, required).
    isInvalid,
    isRequired = numberFieldDefaults.isRequired,
    step = numberFieldDefaults.step,
    className,
    ...rest
  },
  ref,
) {
  return (
    <AriaNumberField
      {...rest}
      ref={ref}
      step={step}
      isDisabled={isDisabled}
      isInvalid={isInvalid}
      isRequired={isRequired}
      className={cx("flex flex-col gap-2", className)}
    >
      <Label className="text-sm font-medium text-[var(--rd-color-text-default)]">
        {label}
        {isRequired && <span aria-hidden="true" className="text-[var(--rd-color-feedback-danger)]"> *</span>}
      </Label>
      <Group className={cx(fieldGroup, fieldGroupSizes[size], heights[size], showStepper && "pe-1")}>
        <Input className="min-w-0 flex-1 bg-transparent tabular-nums outline-none" />
        {showStepper && (
          <>
            <Button slot="decrement" className={stepper}>
              <MinusIcon className="size-4" />
            </Button>
            <Button slot="increment" className={stepper}>
              <PlusIcon className="size-4" />
            </Button>
          </>
        )}
      </Group>
      {description && (
        <Text slot="description" className="text-xs text-[var(--rd-color-text-muted)]">
          {description}
        </Text>
      )}
      <FieldError className="text-xs text-[var(--rd-color-feedback-danger)]">{errorMessage}</FieldError>
    </AriaNumberField>
  );
});

// Generated by rdloom codegen from specs/number-field.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

export const numberFieldSizeValues = ["sm", "md", "lg"] as const;

/** A text field for numbers, with increment and decrement buttons, keyboard stepping, and locale-aware formatting for decimals, currency, units and percentages. */
export interface NumberFieldSpecProps {
  /**
   * Visible label, also the accessible name.
   */
  label: string;
  /**
   * Help text under the field.
   */
  description?: string;
  /**
   * Shown when the value is invalid. Leave out to use the browser's built-in message.
   */
  errorMessage?: string;
  /**
   * Controlled value. An empty field has no number.
   */
  value?: number;
  /**
   * Initial value when uncontrolled.
   */
  defaultValue?: number;
  /**
   * Called with the number, or with a value that is not a number when the field is emptied (test it with Number.isNaN).
   */
  onChange?: (value: number) => void;
  /**
   * Smallest allowed value. Typing below it is corrected on blur.
   */
  minValue?: number;
  /**
   * Largest allowed value.
   */
  maxValue?: number;
  /**
   * How much the buttons and the arrow keys change the value. Values snap to multiples of the step, counted from minValue (or from 0 when there is none).
   * @default 1
   */
  step?: number;
  /**
   * How the number is shown and parsed, e.g. { style: 'currency', currency: 'USD' } or { style: 'percent' }. Follows the user's locale.
   */
  formatOptions?: Intl.NumberFormatOptions;
  /**
   * Shows the − and + buttons. Arrow keys and the mouse wheel stay available.
   * @default true
   */
  showStepper?: boolean;
  /**
   * Field height and text size.
   * @default "md"
   */
  size?: "sm" | "md" | "lg";
  /**
   * Prevents interaction and dims the field.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * Marks the field invalid. Leave it unset to let validation decide.
   */
  isInvalid?: boolean;
  /**
   * Marks the field required and adds an asterisk.
   * @default false
   */
  isRequired?: boolean;
}

export const numberFieldDefaults = {
  step: 1,
  showStepper: true,
  size: "md",
  isDisabled: false,
  isRequired: false,
} as const;

export const numberFieldMeta = {
  "name": "NumberField",
  "version": "0.1.0",
  "status": "experimental",
  "role": "spinbutton"
} as const;
